// Static memory pool avoiding heap fragmentation
#define POOL_BLOCKS 8
#define BLOCK_SIZE  64
static uint8_t s_memory_pool[POOL_BLOCKS][BLOCK_SIZE];
static uint8_t s_allocation_bitmap = 0;

void *pool_alloc(void) {
    for (int i = 0; i < POOL_BLOCKS; i++) {
        if (!(s_allocation_bitmap & (1U << i))) {
            s_allocation_bitmap |= (1U << i);
            return s_memory_pool[i];
        }
    }
    return NULL; // Out of static memory
}

