#include <stdint.h>

#define STATUS_FLAG_CONNECTED (1U << 0)
#define STATUS_FLAG_ALARM     (1U << 1)
#define STATUS_FLAG_BATTERY   (1U << 2)

static uint32_t s_device_status = 0;

void set_alarm(void)    { s_device_status |= STATUS_FLAG_ALARM; }
void clear_alarm(void)  { s_device_status &= ~STATUS_FLAG_ALARM; }
bool is_alarm_on(void)  { return (s_device_status & STATUS_FLAG_ALARM) != 0; }

typedef enum {
    STATE_BOOT,
    STATE_SAMPLE_SENSORS,
    STATE_TRANSMIT_DATA,
    STATE_LOW_POWER_SLEEP
} DeviceState;

static DeviceState s_state = STATE_BOOT;
static uint32_t s_last_sample = 0;

void app_run_step(uint32_t now) {
    switch (s_state) {
        case STATE_BOOT:
            s_state = STATE_SAMPLE_SENSORS;
            break;
        case STATE_SAMPLE_SENSORS:
            if (now - s_last_sample >= 1000) {
                s_last_sample = now;
                s_state = STATE_TRANSMIT_DATA;
            }
            break;
        case STATE_TRANSMIT_DATA:
            s_state = STATE_LOW_POWER_SLEEP;
            break;
        case STATE_LOW_POWER_SLEEP:
            s_state = STATE_SAMPLE_SENSORS;
            break;
    }
}

