// CMSIS-style peripheral register struct definition
typedef struct {
    volatile uint32_t MODER;   // Mode register: input, output, alternate
    volatile uint32_t OTYPER;  // Output type: push-pull, open-drain
    volatile uint32_t OSPEEDR; // Output speed
    volatile uint32_t PUPDR;   // Pull-up / pull-down
    volatile uint32_t IDR;     // Input data register
    volatile uint32_t ODR;     // Output data register
    volatile uint32_t BSRR;    // Bit set / reset register (atomic)
} GPIO_TypeDef;

#define GPIOA_BASE 0x40020000UL
#define GPIOA ((GPIO_TypeDef *)GPIOA_BASE)

// Atomic pin control using BSRR register (no race conditions)
void gpio_set_pin(GPIO_TypeDef *port, uint8_t pin) {
    port->BSRR = (1U << pin);          // Write to lower 16 bits: sets pin HIGH
}

void gpio_reset_pin(GPIO_TypeDef *port, uint8_t pin) {
    port->BSRR = (1U << (pin + 16));   // Write to upper 16 bits: resets pin LOW
}

#include <stdatomic.h>

static atomic_bool s_button_pressed = false;

// Hardware ISR triggered on falling edge of GPIO button
void EXTI0_IRQHandler(void) {
    // 1. Check if interrupt pending flag is set
    if (EXTI->PR & (1U << 0)) {
        // 2. Clear pending flag by writing 1 (hardware clear rule)
        EXTI->PR = (1U << 0);
        // 3. Signal the main loop via atomic variable
        atomic_store(&s_button_pressed, true);
    }
}

// Configuring hardware timer for 1 kHz PWM with 50% duty cycle on 84 MHz clock
void timer_pwm_init(TIM_TypeDef *tim) {
    tim->PSC = 84 - 1;       // 84 MHz / 84 = 1 MHz timer clock (1 us tick)
    tim->ARR = 1000 - 1;     // 1 MHz / 1000 = 1 kHz PWM frequency (1 ms period)
    tim->CCR1 = 500;         // 500 / 1000 = 50% duty cycle
    tim->CCMR1 |= 0x0060;    // PWM mode 1
    tim->CCER |= 0x0001;     // Enable channel 1 output
    tim->CR1 |= 0x0001;      // Enable counter
}

