#define RING_BUFFER_SIZE 64 // Must be power of 2

typedef struct {
    uint8_t buffer[RING_BUFFER_SIZE];
    volatile uint32_t head;
    volatile uint32_t tail;
} RingBuffer;

bool ring_buffer_push(RingBuffer *rb, uint8_t byte) {
    uint32_t next = (rb->head + 1) & (RING_BUFFER_SIZE - 1);
    if (next == rb->tail) return false; // Buffer Full
    rb->buffer[rb->head] = byte;
    rb->head = next;
    return true;
}

bool ring_buffer_pop(RingBuffer *rb, uint8_t *byte) {
    if (rb->head == rb->tail) return false; // Buffer Empty
    *byte = rb->buffer[rb->tail];
    rb->tail = (rb->tail + 1) & (RING_BUFFER_SIZE - 1);
    return true;
}

// Typical I2C master register read sequence in C
bool i2c_read_sensor_register(uint8_t dev_addr, uint8_t reg_addr, uint8_t *data, uint16_t len) {
    if (!i2c_start()) return false;
    if (!i2c_write_byte((dev_addr << 1) | 0)) { i2c_stop(); return false; } // Write device addr
    if (!i2c_write_byte(reg_addr))           { i2c_stop(); return false; } // Select register
    if (!i2c_start()) return false;                                         // Repeated START
    if (!i2c_write_byte((dev_addr << 1) | 1)) { i2c_stop(); return false; } // Read device addr
    for (uint16_t i = 0; i < len; i++) {
        bool send_ack = (i < len - 1); // NACK on last byte
        data[i] = i2c_read_byte(send_ack);
    }
    i2c_stop();
    return true;
}

// Full-duplex SPI byte exchange in C
uint8_t spi_transfer_byte(SPI_TypeDef *spi, uint8_t tx_byte) {
    while (!(spi->SR & SPI_SR_TXE)); // Wait until transmit buffer empty
    spi->DR = tx_byte;               // Write data to start transmission
    while (!(spi->SR & SPI_SR_RXNE)); // Wait until receive buffer not empty
    return (uint8_t)spi->DR;         // Read received byte from shift register
}

// Fast CRC-8 polynomial calculation in C
uint8_t crc8_calculate(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07; // Polynomial x^8 + x^2 + x + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

