// FreeRTOS task declaration and creation in C
void vSensorTask(void *pvParameters) {
    TickType_t xLastWakeTime = xTaskGetTickCount();
    const TickType_t xFrequency = pdMS_TO_TICKS(100); // 100 ms period
    for (;;) {
        sample_adc_sensors();
        // Unblocks exactly every 100ms regardless of execution duration
        vTaskDelayUntil(&xLastWakeTime, xFrequency);
    }
}

// Creating the task with 2048-byte stack and priority 2
xTaskCreate(vSensorTask, "Sensors", 512, NULL, 2, NULL);

// Stack watermark check in FreeRTOS
void monitor_task_stack(TaskHandle_t task_handle, const char *task_name) {
    UBaseType_t words_remaining = uxTaskGetStackHighWaterMark(task_handle);
    printf("[RTOS] Task '%s': stack watermark = %u words (%u bytes free)\n",
           task_name, (unsigned)words_remaining, (unsigned)(words_remaining * sizeof(StackType_t)));
    if (words_remaining < 32) {
        printf("[WARNING] Task '%s' is approaching dangerous stack overflow!\n", task_name);
    }
}

typedef struct {
    uint32_t timestamp;
    float temperature;
    float humidity;
} SensorData;

static QueueHandle_t s_sensor_queue = NULL;

void init_pipeline(void) {
    // Create queue capable of holding 10 SensorData items
    s_sensor_queue = xQueueCreate(10, sizeof(SensorData));
}

void publish_reading(float temp, float hum) {
    SensorData data = { .timestamp = 1000, .temperature = temp, .humidity = hum };
    // Block up to 50ms if queue is full
    xQueueSend(s_sensor_queue, &data, pdMS_TO_TICKS(50));
}

static SemaphoreHandle_t s_i2c_mutex = NULL;

void i2c_safe_read(uint8_t dev_addr, uint8_t *buf, size_t len) {
    if (xSemaphoreTake(s_i2c_mutex, portMAX_DELAY) == pdTRUE) {
        // Critical section: exclusive I2C bus ownership
        hardware_i2c_read(dev_addr, buf, len);
        xSemaphoreGive(s_i2c_mutex);
    }
}

