// Robust TCP send loop in C
bool socket_send_all(int sock, const uint8_t *data, size_t len) {
    size_t total_sent = 0;
    while (total_sent < len) {
        ssize_t sent = send(sock, data + total_sent, len - total_sent, 0);
        if (sent <= 0) return false; // Connection closed or socket error
        total_sent += (size_t)sent;
    }
    return true;
}

// Non-blocking connect with timeout in C
bool nonblocking_connect(int sock, struct sockaddr_in *addr, uint32_t timeout_sec) {
    fcntl(sock, F_SETFL, O_NONBLOCK);
    connect(sock, (struct sockaddr *)addr, sizeof(*addr));

    fd_set write_fds;
    FD_ZERO(&write_fds);
    FD_SET(sock, &write_fds);
    struct timeval tv = { .tv_sec = timeout_sec, .tv_usec = 0 };

    int res = select(sock + 1, NULL, &write_fds, NULL, &tv);
    return (res > 0 && FD_ISSET(sock, &write_fds));
}

