// Deep sleep transition in embedded C (ESP-IDF / Cortex-M)
void enter_deep_sleep(uint64_t sleep_time_us) {
    printf("[POWER] Entering deep sleep for %llu ms...\n", sleep_time_us / 1000ULL);
    // 1. Configure RTC wake timer
    esp_sleep_enable_timer_wakeup(sleep_time_us);
    // 2. Isolate GPIO pins to prevent leakage currents
    rtc_gpio_isolate(GPIO_NUM_12);
    // 3. Enter deep sleep (CPU and RAM power down)
    esp_deep_sleep_start();
}

