// Battery life calculation in C
float calculate_battery_life_years(float i_active_ma, float t_active_sec,
                                   float i_sleep_ma, float t_sleep_sec,
                                   float battery_capacity_mah) {
    float t_cycle = t_active_sec + t_sleep_sec;
    float i_avg_ma = ((i_active_ma * t_active_sec) + (i_sleep_ma * t_sleep_sec)) / t_cycle;
    float usable_capacity = battery_capacity_mah * 0.85f; // 85% derating
    float hours = usable_capacity / i_avg_ma;
    return hours / (24.0f * 365.25f);
}

