void PVD_IRQHandler(void) {
    // Supply voltage dropped below 2.7V!
    disable_radio_transmitters();
    abort_flash_operations();
    s_rtc_emergency_shutdown_flag = 1;
    enter_deep_sleep(UINT64_MAX); // Sleep indefinitely until battery replaced
}

